def lpHaarRefineAt (n₀ : ℕ) (S : Finset (Fin (2 ^ n₀))) (n : ℕ) :
    Finset (Fin (2 ^ n)) :=
  if hn : n₀ ≤ n then (Nat.add_sub_of_le hn) ▸ lpHaarRefine n₀ S (n - n₀) else ∅

